      { rank: 7, title: 'Agent from Above', gradient: 'poster-gradient-2' },
      { rank: 8, title: 'Boyfriend on Demand', gradient: 'poster-gradient-3' },
      { rank: 9, title: 'KPop Demon Hunters', gradient: 'poster-gradient-4' },
      { rank: 10, title: 'Emily in Paris', gradient: 'poster-gradient-5' },
    ];

    const carouselEl = document.getElementById('carousel');
    trending.forEach(item => {
      const wrapper = document.createElement('div');
      wrapper.className = 'flex items-end flex-shrink-0';
      wrapper.innerHTML = `
        <span class="rank-number relative z-10 -mr-3 sm:-mr-4 mb-1">${item.rank}</span>
