    function scrollCarousel(direction) {
      const el = document.getElementById('carousel');
      const scrollAmount = el.clientWidth * 0.6;
      el.scrollBy({ left: direction * scrollAmount, behavior: 'smooth' });
    }

    // Touch swipe support
    let touchStartX = 0;
    let touchEndX = 0;
    carouselEl.addEventListener('touchstart', e => {
      touchStartX = e.changedTouches[0].screenX;
    }, { passive: true });
    carouselEl.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        scrollCarousel(diff > 0 ? 1 : -1);
      }
    }, { passive: true });

    // FAQ data
    const faqs = [
      {
        q: 'What is StreamWave?',
        a: 'StreamWave is a streaming service that offers a wide variety of award-winning TV programmes, films, anime, documentaries and more — on thousands of internet-connected devices. You can watch as much as you want, whenever you want, without a single advert — all for one low monthly price. There\'s always something new to discover, and new TV programmes and films are added every week!'
      },
      {
        q: 'How much does StreamWave cost?',
        a: 'Watch StreamWave on your smartphone, tablet, smart TV, laptop or streaming device, all for one fixed monthly fee. Plans range from $15.98 to $29.98/month.'
      },
      {
        q: 'Where can I watch?',
        a: 'Watch anywhere, anytime. Sign in with your StreamWave account to watch instantly on the web from your personal computer or on any internet-connected device that offers the StreamWave app, including smart TVs, smartphones, tablets, streaming media players and game consoles. You can also download your favourite programmes with the iOS or Android app. Use downloads to watch while you\'re on the go and without an internet connection. Take StreamWave with you anywhere.'
      },
      {
        q: 'How do I cancel?',
        a: 'StreamWave is flexible. You can easily cancel your account online in two clicks. There are no cancellation fees — start or stop your account at any time.'
      },
      {
        q: 'What can I watch on StreamWave?',
        a: 'StreamWave has an extensive library of feature films, documentaries, series, anime, award-winning StreamWave originals, and more. Watch as much as you want, any time you want.'
      },
      {
        q: 'Is StreamWave good for children?',
        a: 'The StreamWave Children\'s experience is included in your membership to give parents control while children enjoy family-friendly TV programmes and films in their own space. Children\'s profiles come with PIN-protected parental controls that let you restrict the maturity rating of content children can watch and block specific titles you don\'t want children to see.'
      },
    ];

    const faqContainer = document.getElementById('faq-container');
    let openIndex = -1;

    faqs.forEach((faq, i) => {
      const item = document.createElement('div');
      item.innerHTML = `
        <button
          class="w-full flex items-center justify-between bg-sw-gray hover:bg-[#3a3a3a] transition-colors px-5 sm:px-6 py-5 text-left rounded-sm"
          onclick="toggleFaq(${i})"
          aria-expanded="false"
          aria-controls="faq-answer-${i}"
        >
          <span class="text-base sm:text-lg md:text-xl font-medium pr-4">${faq.q}</span>
          <svg id="faq-icon-${i}" class="faq-icon w-7 h-7 sm:w-8 sm:h-8 flex-shrink-0 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M12 4v16m8-8H4"/>
          </svg>
        </button>
        <div id="faq-answer-${i}" class="faq-answer bg-sw-gray mt-px rounded-sm">
          <p class="px-5 sm:px-6 py-5 text-base sm:text-lg text-sw-gray-text leading-relaxed">${faq.a}</p>
        </div>
      `;
      faqContainer.appendChild(item);
    });

    function toggleFaq(index) {
      const wasOpen = openIndex === index;

      // Close currently open
      if (openIndex >= 0) {
        const prevAnswer = document.getElementById(`faq-answer-${openIndex}`);
        const prevIcon = document.getElementById(`faq-icon-${openIndex}`);
        const prevBtn = prevAnswer.previousElementSibling;
        prevAnswer.classList.remove('open');
        prevIcon.classList.remove('rotated');
        prevBtn.setAttribute('aria-expanded', 'false');
